// Clock enable generation
// 16000000 = 48000000*1/3 Hz from clk48
`ifdef VERILATOR_KEEP_CEN /* verilator tracing_on */ `else /* verilator tracing_off */ `endif
jtframe_gated_cen #(.W(1),.NUM(1),.DEN(3),.MFREQ(48000)) u_cen0_clk48(
    .rst    ( rst          ),
    .clk    ( clk48 ),
    .busy   ( 1'b0    ),
    .cen    ( { cen_16 } ),
    .fave   (              ),
    .fworst (              )
); /* verilator tracing_off */

// 8000000 = 48000000*1/6 Hz from clk48
`ifdef VERILATOR_KEEP_CEN /* verilator tracing_on */ `else /* verilator tracing_off */ `endif
jtframe_gated_cen #(.W(1),.NUM(1),.DEN(6),.MFREQ(48000)) u_cen1_clk48(
    .rst    ( rst          ),
    .clk    ( clk48 ),
    .busy   ( 1'b0    ),
    .cen    ( { cen_8 } ),
    .fave   (              ),
    .fworst (              )
); /* verilator tracing_off */

// 18432000 = 48000000*48/125 Hz from clk48
`ifdef VERILATOR_KEEP_CEN /* verilator tracing_on */ `else /* verilator tracing_off */ `endif
jtframe_gated_cen #(.W(1),.NUM(48),.DEN(125),.MFREQ(48000)) u_cen2_clk48(
    .rst    ( rst          ),
    .clk    ( clk48 ),
    .busy   ( (pcm0_cs & ~pcm0_ok) | (pcm1_cs & ~pcm1_ok)    ),
    .cen    ( { cen_pcm } ),
    .fave   (              ),
    .fworst (              )
); /* verilator tracing_off */

`ifndef NOSOUND
`ifdef VERILATOR_KEEP_AUDIO /* verilator tracing_on */ `else /* verilator tracing_off */ `endif
assign mute=0;

jtframe_rcmix #(
    .W0(16),
    .W1(16),
    .STEREO0( 1),
    .STEREO1( 1),
    .STEREO2( 0),
    .STEREO3( 0),
    .STEREO4( 0),
    .STEREO5( 0),
    .DCRM0  ( 0),
    .DCRM1  ( 0),
    .DCRM2  ( 0),
    .DCRM3  ( 0),
    .DCRM4  ( 0),
    .DCRM5  ( 0),
    .STEREO (      1),
    // Fractional cen for 192kHz
    .FRACW( 9), .FRACN(1), .FRACM(250)
) u_rcmix(
`ifdef JTFRAME_CLK48
    .rst    ( rst48     ),
    .clk    ( clk48     ),
`else
    .rst    ( rst       ),
    .clk    ( clk       ),
`endif
    .mute   ( mute      ),
    .sample ( sample    ),
    .ch_en  ( snd_en    ),
    .gpole  ( 15'h3F66 ),  // 19894 Hz 
    .ch0    ( { pcm0_l,pcm0_r } ),
    .ch1    ( { pcm1_l,pcm1_r } ),
    .ch2    ( 16'd0 ),
    .ch3    ( 16'd0 ),
    .ch4    ( 16'd0 ),
    .ch5    ( 16'd0 ),
    .p0     ( {15'h00,15'h4B9B}), // 15392 Hz, 0 Hz 
    .p1     ( {15'h00,15'h4B9B}), // 15392 Hz, 0 Hz 
    .p2     ( 30'h0), 
    .p3     ( 30'h0), 
    .p4     ( 30'h0), 
    .p5     ( 30'h0), 
    .g0     ( 8'h80 ), // 1.00  pcm0
    .g1     ( 8'h80 ), // 1.00  pcm1
    .g2     ( 8'h00 ), // 0.00 
    .g3     ( 8'h00 ), // 0.00 
    .g4     ( 8'h00 ), // 0.00 
    .g5     ( 8'h00 ), // 0.00 
    .gain   ( snd_vol   ),
    .mixed  ({ snd_left, snd_right}),
    .peak   ( snd_peak  ),
    .vu     ( snd_vu    )
);
`else
assign { snd_left, snd_right}=0;
assign snd_vu   = 0;
assign snd_peak = 0;
wire ncs;
jtframe_frac_cen #(.WC(9)) u_cen192(
    .clk    ( clk       ),
    .n      ( 1 ),
    .m      ( 250 ),
    .cen    ( {  ncs,sample }  ), // sample is always 192 kHz
    .cenb   (                  )
);
`endif
endmodule
